```go
package main

import (
	"encoding/json"
	"fmt"
)

func main() {
	var value any
	if err := json.Unmarshal([]byte(`{"active":true,"scores":[4,5]}`), &value); err != nil {
		panic(err)
	}
	object := value.(map[string]any)
	scores := object["scores"].([]any)
	fmt.Printf("%T %T %T\n", object["active"], scores, scores[0])
}
```
The integer-looking score is a float64 because the destination did not provide a numeric type.

```go
package main

import (
	"encoding/json"
	"fmt"
	"strings"
)

func main() {
	dec := json.NewDecoder(strings.NewReader(`{"id":9007199254740993}`))
	dec.UseNumber()
	var object map[string]any
	if err := dec.Decode(&object); err != nil {
		panic(err)
	}
	n := object["id"].(json.Number)
	id, err := n.Int64()
	if err != nil {
		panic(err)
	}
	fmt.Println(id)
}
```
The token remains json.Number until the checked int64 conversion, so the exact integer is retained.

```go
package main

import (
	"encoding/json"
	"fmt"
)

type Envelope struct {
	Type string          `json:"type"`
	Data json.RawMessage `json:"data"`
}
type UserCreated struct {
	ID int `json:"id"`
}

func main() {
	input := []byte(`{"type":"user.created","data":{"id":9}}`)
	var event Envelope
	if err := json.Unmarshal(input, &event); err != nil {
		panic(err)
	}
	if event.Type != "user.created" {
		panic("unsupported event")
	}
	var data UserCreated
	if err := json.Unmarshal(event.Data, &data); err != nil {
		panic(err)
	}
	fmt.Println(event.Type, data.ID)
}
```
Only the variant payload is delayed; the discriminator remains a typed field from the first decode.
